// A função já diz tudo: os parâmetros e a forma do objeto que devolve.
function criarSessao(utilizador: string, minutos: number) {
  return { utilizador, expiraEm: minutos * 60, ativa: true };
}

// typeof faz a ponte do valor para o tipo: a função vista como tipo de função.
type FuncaoCriarSessao = typeof criarSessao;
// (utilizador: string, minutos: number) => { utilizador: string; expiraEm: number; ativa: boolean }

// ReturnType recebe um TIPO, por isso o typeof é obrigatório pelo meio.
type Sessao = ReturnType<typeof criarSessao>;

const sessao: Sessao = criarSessao("ana", 30);
console.log(sessao.expiraEm, sessao.ativa); // 1800 true

const outra: FuncaoCriarSessao = criarSessao;
console.log(outra("bruno", 1).expiraEm); // 60

// @ts-expect-error criarSessao é um valor; sem typeof não há tipo nenhum para passar
type Errada = ReturnType<criarSessao>;
export {};

// A definição real, tal como está na biblioteca padrão, numa linha:
type MeuReturnType<T extends (...args: any) => any> =
  T extends (...args: any) => infer R ? R : any;

// É o TipoDeRetorno escrito à mão no módulo anterior, com uma constraint a mais.
function calcularFatura(valor: number, taxa: number) {
  return { base: valor, imposto: valor * taxa, total: valor + valor * taxa };
}

type Fatura = MeuReturnType<typeof calcularFatura>;
type FaturaDaLib = ReturnType<typeof calcularFatura>;

const fatura: Fatura = calcularFatura(100, 0.25);
const mesma: FaturaDaLib = fatura; // são o mesmo tipo
console.log(mesma.total); // 125

// Sobrecargas (Módulo 03): a lista tem duas assinaturas visíveis.
function medir(valor: string): number;
function medir(valor: readonly unknown[]): number[];
function medir(valor: string | readonly unknown[]): number | number[] {
  return typeof valor === "string" ? valor.length : valor.map(() => 1);
}

// O compilador resolve pela ÚLTIMA assinatura da lista, não pela união das duas.
type RetornoMedir = ReturnType<typeof medir>; // number[]
const medido: RetornoMedir = medir(["a", "b"]);
console.log(medido); // [ 1, 1 ]

// @ts-expect-error RetornoMedir é number[]; o number da primeira sobrecarga perdeu-se
const escalar: RetornoMedir = 3;
export {};

// A definição real: o infer ocupa o lugar da lista de parâmetros.
type MeusParameters<T extends (...args: any) => any> =
  T extends (...args: infer P) => any ? P : never;

function enviarEmail(destino: string, assunto: string, urgente: boolean): string {
  return `${destino} | ${assunto} | ${urgente ? "urgente" : "normal"}`;
}

// O resultado é um TUPLO, com os nomes dos parâmetros como rótulos.
type ArgsEmail = Parameters<typeof enviarEmail>;
// [destino: string, assunto: string, urgente: boolean]
type IguaisAosMeus = MeusParameters<typeof enviarEmail>;

const args: ArgsEmail = ["ana@exemplo.pt", "Relatório", true];
const mesmos: IguaisAosMeus = args;
console.log(enviarEmail(...mesmos)); // ana@exemplo.pt | Relatório | urgente

// Sendo um tuplo, aceita acesso por índice como qualquer outro.
type Destino = ArgsEmail[0]; // string
type Urgente = ArgsEmail[2]; // boolean
const destino: Destino = "bruno@exemplo.pt";
const urgente: Urgente = false;
console.log(destino, urgente); // bruno@exemplo.pt false

// O par Parameters + ReturnType descreve um embrulho que não altera a assinatura.
function comContagem<T extends (...args: any[]) => any>(fn: T) {
  let vezes = 0;
  const embrulhada = (...args: Parameters<T>): ReturnType<T> => {
    vezes += 1;
    return fn(...args);
  };
  return { embrulhada, vezes: () => vezes };
}

const contado = comContagem(enviarEmail);
console.log(contado.embrulhada("ana@exemplo.pt", "Olá", false)); // ana@exemplo.pt | Olá | normal
console.log(contado.vezes()); // 1

// @ts-expect-error o tuplo tem três posições; faltam argumentos
const incompleto: ArgsEmail = ["ana@exemplo.pt", "Relatório"];

// A definição real é recursiva: enquanto encontrar um then, volta a desembrulhar.
type MeuAwaited<T> = T extends null | undefined
  ? T
  : T extends object & { then(aoResolver: infer F, ...resto: infer _): any }
    ? F extends (valor: infer V, ...resto: infer _) => any
      ? MeuAwaited<V>
      : never
    : T;

// Uma promessa dentro de outra só se consegue exprimir na assinatura:
// em tempo de execução Promise.resolve já achata o valor sozinho.
declare function obterPerfil(): Promise<Promise<{ nome: string }>>;

type Perfil = Awaited<ReturnType<typeof obterPerfil>>; // { nome: string }
type PerfilPeloMeu = MeuAwaited<ReturnType<typeof obterPerfil>>; // o mesmo
const perfil: Perfil = { nome: "Ana" };
const perfil2: PerfilPeloMeu = perfil;

// Um tipo que não é promessa sai como entrou: o último ramo devolve T.
type Numero = Awaited<number>; // number
const numero: Numero = 7;

// Qualquer thenable é desembrulhado, mesmo sem ser uma Promise.
interface Tarefa {
  then(aoResolver: (valor: string) => void): void;
}
type ValorDaTarefa = Awaited<Tarefa>; // string
const valorDaTarefa: ValorDaTarefa = "pronto";

console.log(perfil2.nome, numero, valorDaTarefa); // Ana 7 pronto

// @ts-expect-error Awaited já tirou a promessa: Perfil é o objeto, não a promessa
const enganado: Perfil = Promise.resolve({ nome: "Ana" });

class Relatorio {
  constructor(
    public titulo: string,
    public linhas: number,
  ) {}
  resumo(): string {
    return `${this.titulo}: ${this.linhas} linhas`;
  }
}

// typeof Relatorio é o tipo do CONSTRUTOR; InstanceType dá o tipo das instâncias.
type Instancia = InstanceType<typeof Relatorio>; // Relatorio
type ArgsConstrutor = ConstructorParameters<typeof Relatorio>;
// [titulo: string, linhas: number]

const argsConstrutor: ArgsConstrutor = ["Vendas", 12];
const relatorio: Instancia = new Relatorio(...argsConstrutor);
console.log(relatorio.resumo()); // Vendas: 12 linhas

// ThisParameterType e OmitThisParameter trabalham sobre o this declarado (Módulo 03).
function formatar(this: { moeda: string }, valor: number): string {
  return `${valor.toFixed(2)} ${this.moeda}`;
}

type Contexto = ThisParameterType<typeof formatar>; // { moeda: string }
type SemThis = OmitThisParameter<typeof formatar>; // (valor: number) => string

const contexto: Contexto = { moeda: "EUR" };
const ligada: SemThis = formatar.bind(contexto);
console.log(ligada(20)); // 20.00 EUR

try {
  // @ts-expect-error formatar exige um this com moeda; só a versão ligada dispensa
  formatar(20);
} catch {
  console.log("sem this não há moeda"); // sem this não há moeda
}

// O embrulho não conhece a função que recebe: descreve-a com Parameters e ReturnType.
// Sem o Awaited, o retorno seria Promise<ReturnType<T>>, ou seja Promise<Promise<...>>.
function comCache<T extends (...args: any[]) => Promise<any>>(
  fn: T,
): (...args: Parameters<T>) => Promise<Awaited<ReturnType<T>>> {
  const cache = new Map<string, Promise<Awaited<ReturnType<T>>>>();
  return (...args: Parameters<T>) => {
    const chave = JSON.stringify(args);
    const guardado = cache.get(chave);
    if (guardado !== undefined) {
      console.log(`cache: ${chave}`);
      return guardado;
    }
    const nova: Promise<Awaited<ReturnType<T>>> = fn(...args);
    cache.set(chave, nova);
    return nova;
  };
}

let idas = 0;
async function precoDe(artigo: string, quantidade: number): Promise<number> {
  idas += 1;
  return artigo.length * quantidade;
}

const precoComCache = comCache(precoDe);

async function principal(): Promise<void> {
  // O tipo de total é number, não Promise<number>: foi o Awaited que o achatou.
  const total: number = await precoComCache("livro", 2);
  console.log(total); // 10

  const repetido = await precoComCache("livro", 2); // escreve: cache: ["livro",2]
  console.log(repetido); // 10
  console.log(idas); // 1
}

void principal();

