function criarEncomenda(cliente: string, artigos: string[], expresso: boolean) {
  return {
    cliente,
    artigos,
    expresso,
    portes: expresso ? 9.9 : 3.5,
  };
}

type Encomenda = ReturnType<typeof criarEncomenda>;
type ArgsEncomenda = Parameters<typeof criarEncomenda>;
type Cliente = ArgsEncomenda[0];

const args: ArgsEncomenda = ["Ana", ["livro", "caneta"], true];
const encomenda: Encomenda = criarEncomenda(...args);
const cliente: Cliente = encomenda.cliente;

console.log(cliente, encomenda.portes); // Ana 9.9
console.log(encomenda.artigos.length); // 2
export {};

type RetornoDe<T extends (...args: any) => any> =
  T extends (...args: any) => infer R ? R : never;

type ArgumentosDe<T extends (...args: any) => any> =
  T extends (...args: infer P) => any ? P : never;

function comMedicao<T extends (...args: any[]) => any>(etiqueta: string, fn: T) {
  const chamadas: string[] = [];
  const embrulhada = (...args: ArgumentosDe<T>): RetornoDe<T> => {
    chamadas.push(`${etiqueta}(${args.length} argumentos)`);
    return fn(...args);
  };
  return { embrulhada, historico: () => chamadas };
}

function juntar(separador: string, ...partes: string[]): string {
  return partes.join(separador);
}

const medido = comMedicao("juntar", juntar);
console.log(medido.embrulhada("-", "a", "b", "c")); // a-b-c
console.log(medido.historico()); // [ 'juntar(4 argumentos)' ]

// Os utilitários escritos à mão e os da biblioteca são o mesmo tipo.
const meus: ArgumentosDe<typeof juntar> = ["/", "x"];
const daLib: Parameters<typeof juntar> = meus;
console.log(juntar(...daLib)); // x

// O utilitário pedido: o retorno da função, já desembrulhado.
type ResultadoDe<T extends (...args: any) => any> = Awaited<ReturnType<T>>;

// Uma assinatura com promessa dentro de promessa, para provar a recursão.
declare function obterPerfilRemoto(
  id: number,
): Promise<Promise<{ id: number; nome: string }>>;

type Perfil = ResultadoDe<typeof obterPerfilRemoto>; // { id: number; nome: string }
const perfil: Perfil = { id: 1, nome: "Ana" };
console.log(perfil.nome); // Ana

// Uma função síncrona também passa: Awaited de um tipo que não é promessa é ele próprio.
function contarPalavras(texto: string): number {
  return texto.split(" ").length;
}
type Contagem = ResultadoDe<typeof contarPalavras>; // number
const contagem: Contagem = contarPalavras("um dois três");
console.log(contagem); // 3

// E a versão assíncrona da mesma função dá exatamente o mesmo tipo.
async function contarPalavrasAsync(texto: string): Promise<number> {
  return texto.split(" ").length;
}
type ContagemAsync = ResultadoDe<typeof contarPalavrasAsync>; // number
const mesma: ContagemAsync = contagem;
console.log(mesma); // 3

async function principal(): Promise<void> {
  const valor: ResultadoDe<typeof contarPalavrasAsync> =
    await contarPalavrasAsync("a b");
  console.log(valor); // 2
}
void principal();

// @ts-expect-error ResultadoDe já tirou a promessa: Contagem é number
const errado: Contagem = Promise.resolve(3);

type FuncaoAssincrona = (...args: any[]) => Promise<any>;

// O embrulho preserva os parâmetros e devolve o valor já desembrulhado.
function comTentativas<T extends FuncaoAssincrona>(
  fn: T,
  maximo: number,
): (...args: Parameters<T>) => Promise<Awaited<ReturnType<T>>> {
  return async (...args: Parameters<T>): Promise<Awaited<ReturnType<T>>> => {
    let ultimoErro: unknown;
    for (let tentativa = 1; tentativa <= maximo; tentativa += 1) {
      try {
        return await fn(...args);
      } catch (erro) {
        ultimoErro = erro;
        console.log(`tentativa ${tentativa} falhou`);
      }
    }
    throw ultimoErro;
  };
}

let chamadas = 0;
async function lerConfiguracao(
  nome: string,
): Promise<{ nome: string; versao: number }> {
  chamadas += 1;
  if (chamadas < 3) {
    throw new Error("indisponível");
  }
  return { nome, versao: chamadas };
}

const lerComTentativas = comTentativas(lerConfiguracao, 5);

async function principal(): Promise<void> {
  // O await devolve o objeto, não a promessa: o Awaited está na assinatura.
  const config: { nome: string; versao: number } = await lerComTentativas("app");
  console.log(config); // { nome: 'app', versao: 3 }

  chamadas = 0;
  const poucasTentativas = comTentativas(lerConfiguracao, 2);
  try {
    await poucasTentativas("app");
  } catch (erro) {
    console.log((erro as Error).message); // indisponível
  }
}
void principal();
